import anthropic

client = anthropic.Anthropic()


def preguntar(texto: str, sistema: str, max_tokens: int = 1024) -> str | None:
    """Hace una llamada y devuelve el texto, o None si no hubo respuesta útil."""
    try:
        r = client.messages.create(
            model="claude-opus-5-5",
            max_tokens=max_tokens,
            system=sistema,
            messages=[{"role": "user", "content": texto}],
        )
    except anthropic.APIError as e:
        print("Error de la API:", e)
        return None
    if r.stop_reason == "refusal":
        print("El modelo no respondió esta solicitud.")
        return None
    if r.stop_reason == "max_tokens":
        print("Aviso: la respuesta se cortó; sube max_tokens.")
    print(f"tokens: {r.usage.input_tokens} entrada, {r.usage.output_tokens} salida")
    return "".join(b.text for b in r.content if b.type == "text")

