import anthropic

client = anthropic.Anthropic()

SISTEMA = (
    "Resumes correos de clientes de un taller en UNA línea de máximo 20 palabras, "
    "en español, indicando qué pide el cliente."
)


def resumir(correo: str) -> str:
    try:
        r = client.messages.create(
            model="claude-haiku-5-5",
            max_tokens=200,
            system=SISTEMA,
            messages=[{"role": "user", "content": f"<correo>\n{correo}\n</correo>"}],
        )
    except anthropic.APIError as e:
        return f"(error: {e})"
    if r.stop_reason == "refusal":
        return "(sin respuesta)"
    return "".join(b.text for b in r.content if b.type == "text").strip()


print(resumir("Buenas, llevé la camioneta el lunes y todavía no me dicen cuándo está lista."))

def fragmentar(texto: str, palabras: int = 200, solape: int = 30) -> list[str]:
    lista = texto.split()
    paso = palabras - solape
    trozos = []
    for inicio in range(0, len(lista), paso):
        trozos.append(" ".join(lista[inicio:inicio + palabras]))
        if inicio + palabras >= len(lista):
            break
    return trozos


print(len(fragmentar("palabra " * 500)))  # 3 fragmentos

