import anthropic
from anthropic import beta_tool

client = anthropic.Anthropic()
INVENTARIO = {"FLT-2201": (14, 650.0), "BAT-12V70": (0, 7900.0)}


@beta_tool
def consultar_inventario(codigo: str) -> str:
    """Devuelve las unidades disponibles y el precio en RD$ de una pieza.

    Args:
        codigo: Código de la pieza, por ejemplo FLT-2201.
    """
    if codigo not in INVENTARIO:
        return f"No existe la pieza {codigo}. Pide al cliente que confirme el código."
    unidades, precio = INVENTARIO[codigo]
    return f"{codigo}: {unidades} unidades, RD${precio:,.2f}"


runner = client.beta.messages.tool_runner(
    model="claude-opus-5-5",
    max_tokens=4096,
    system="Atiendes consultas de piezas de un taller. Responde en español y en pocas líneas.",
    tools=[consultar_inventario],
    messages=[{"role": "user", "content": "¿Hay batería BAT-12V70?"}],
)
for mensaje in runner:
    for b in mensaje.content:
        if b.type == "text":
            print(b.text)

